def _clock_at_tz(time, tz, units):
    """
    Internal function to calculate clock time at a specific timezone.
    Returns the time offset as a timedelta in the specified units.
    """

    # Ensure time is in numpy datetime64[ns] format
    if isinstance(time, pd.Timestamp):
        time_ns = np.array([time.to_datetime64()], dtype='datetime64[ns]')
    elif isinstance(time, np.datetime64):
        if np.isnat(time):
            time_ns = np.array([time], dtype='datetime64[ns]')
        else:
            time_ns = np.array([time], dtype='datetime64[ns]')
    elif isinstance(time, np.ndarray):
        if time.dtype != 'datetime64[ns]':
            time_ns = time.astype('datetime64[ns]')
        else:
            time_ns = time
    else:
        time_ns = np.array([time], dtype='datetime64[ns]')

    # Ensure it's always an array
    if time_ns.ndim == 0:
        time_ns = np.array([time_ns])

    # Convert to pandas for timezone handling
    ts_array = pd.to_datetime(time_ns)

    if tz is None:
        # No timezone specified - use UTC interpretation
        # The time values are interpreted as-is (no conversion)
        offsets = ts_array
    else:
        # Convert to the target timezone
        # First ensure ts_array is timezone-naive or UTC
        if ts_array.tz is None:
            # Treat as UTC
            ts_utc = ts_array.tz_localize('UTC')
        else:
            ts_utc = ts_array.tz_convert('UTC')

        # Convert to target timezone
        ts_target = ts_utc.tz_convert(tz)

        # Calculate offset from UTC at that time
        # Get the local time at the target timezone
        offsets = ts_target

    # Calculate time differences in nanoseconds from epoch
    epoch = pd.Timestamp('1970-01-01', tz='UTC' if tz else None)

    if tz is None:
        # Just use the time as-is (no TZ conversion)
        epoch_naive = pd.Timestamp('1970-01-01')
        total_ns = (ts_array - epoch_naive).values
    else:
        # Get the offset in the target timezone
        if isinstance(offsets, pd.DatetimeIndex):
            # Remove timezone info to get naive local time
            local_times = offsets.tz_localize(None)
        else:
            local_times = offsets

        epoch_naive = pd.Timestamp('1970-01-01')
        total_ns = (local_times - epoch_naive).values

    # Convert to requested units
    total_seconds = total_ns / 1e9

    if units == "secs":
        result = total_seconds
    elif units == "mins":
        result = total_seconds / 60
    elif units == "hours":
        result = total_seconds / 3600
    elif units == "days":
        result = total_seconds / 86400
    elif units == "weeks":
        result = total_seconds / (7 * 86400)
    else:
        result = total_seconds

    # Return as timedelta-like array
    if len(result) == 1:
        return result[0]
    return result
